function gerarNumeroAleatorio(e,o){return e=Math.ceil(e),o=Math.floor(o),Math.floor(Math.random()*(o-e+1))+e}let num1=gerarNumeroAleatorio(1,10),num2=(console.log("Número aleatório entre 1 e 10: "+num1),gerarNumeroAleatorio(50,100)),num3=(console.log("Número aleatório entre 50 e 100: "+num2),gerarNumeroAleatorio(0,1));function gerarNumeroAleatorioFlutuante(e,o){return Math.random()*(o-e)+e}console.log("Número aleatório entre 0 e 1: "+num3);let numFlutuante=gerarNumeroAleatorioFlutuante(0,1);console.log("Número aleatório flutuante entre 0 e 1: "+numFlutuante);